 Project name                  : ADR SoC
 File Name                     : adr_ddr.sv
 Module/class Name             : adr_ddr
 Author                        : Vijay Bogati
 Description                   : DDR4 memory: a LiteDRAM core, generated by scripts/gen_ddr.py
***************************************************************/

// ADR SoC - DDR4 memory: a LiteDRAM core, generated by scripts/gen_ddr.py.
// The generated core here includes LiteDRAM's DFI-level memory model, in place of a PHY and a
// memory device, so it is for simulation only. It runs on clk_i and starts under hardware
// control, so software has no init sequence to run. A real part needs a core generated with
// its own PHY and geometry, its own clock and a software init sequence, with its user port
// waiting for that init to finish.
//
// The generated core has no reset input of its own: it starts from its initial values, and a
// system reset doesn't reset it, so memory contents survive a warm reset. To keep a transaction
// from being cut by a warm reset, adr_ddr_drain sits in front of the atomics unit: the reset
// generator raises drain_i before a watchdog, software or debug reset, the gate stops new
// transactions, and the reset waits for idle_o (or a timeout, recorded in system control).
//
// RISC-V atomics (AMOs, and LR/SC) arrive as AXI atomic transactions, which LiteDRAM can't
// perform, so an atomics unit in front of the core carries them out as plain reads and writes.
//
// Control registers: LiteDRAM's own, listed in rtl/third_party_ip/ddr/csr.csv. 32-bit accesses.

`include "axi/assign.svh"

module adr_ddr #(
  parameter int unsigned AddrBits  = 25,
  parameter int unsigned AddrWidth = 64,
  parameter int unsigned DataWidth = 64,
  parameter int unsigned IdWidth   = 1,
  parameter int unsigned UserWidth = 1,
  parameter type         req_t     = logic,
  parameter type         resp_t    = logic
) (
  input  logic        clk_i,
  input  logic        rst_ni,      // system reset: the drain gate and the atomics unit, see above
  // Drain before a warm reset (adr_rst_gen)
  input  logic        drain_i,
  output logic        idle_o,
  // Memory port, from the crossbar
  input  req_t        slv_req_i,
  output resp_t       slv_resp_o,
  // Control registers
  input  logic        psel_i,
  input  logic        penable_i,
  input  logic        pwrite_i,
  input  logic [15:0] paddr_i,
  input  logic [31:0] pwdata_i,
  output logic [31:0] prdata_o,
  output logic        pready_o,
  output logic        pslverr_o
);

  AXI_BUS #(
    .AXI_ADDR_WIDTH ( AddrWidth ),
    .AXI_DATA_WIDTH ( DataWidth ),
    .AXI_ID_WIDTH   ( IdWidth   ),
    .AXI_USER_WIDTH ( UserWidth )
  ) bus_in (), slv ();

  req_t  gated_req;
  resp_t gated_resp;

  adr_ddr_drain #(
    .req_t  ( req_t  ),
    .resp_t ( resp_t )
  ) i_drain (
    .clk_i,
    .rst_ni,
    .drain_i,
    .idle_o,
    .slv_req_i  ( slv_req_i  ),
    .slv_resp_o ( slv_resp_o ),
    .mst_req_o  ( gated_req  ),
    .mst_resp_i ( gated_resp )
  );

  `AXI_ASSIGN_FROM_REQ(bus_in, gated_req)
  `AXI_ASSIGN_TO_RESP(gated_resp, bus_in)

  axi_riscv_atomics_wrap #(
    .AXI_ADDR_WIDTH     ( AddrWidth ),
    .AXI_DATA_WIDTH     ( DataWidth ),
    .AXI_ID_WIDTH       ( IdWidth   ),
    .AXI_USER_WIDTH     ( UserWidth ),
    .AXI_MAX_WRITE_TXNS ( 1         ),
    .RISCV_WORD_WIDTH   ( 64        )
  ) i_atomics (
    .clk_i,
    .rst_ni,
    .slv ( bus_in ),
    .mst ( slv    )
  );

  // slv: the memory side of the atomics unit, driving the LiteDRAM user port.
  assign slv.b_user = '0;
  assign slv.r_user = '0;

  litedram_core i_core (
    .clk                     ( clk_i                     ),
    .init_done               (                           ),
    .init_error              (                           ),
    .sim_trace               ( 1'b0                      ),
    .user_clk                (                           ),
    .user_rst                (                           ),
    .user_port_axi_0_awvalid ( slv.aw_valid              ),
    .user_port_axi_0_awready ( slv.aw_ready              ),
    .user_port_axi_0_awaddr  ( slv.aw_addr[AddrBits-1:0] ),
    .user_port_axi_0_awburst ( slv.aw_burst              ),
    .user_port_axi_0_awlen   ( slv.aw_len                ),
    .user_port_axi_0_awsize  ( slv.aw_size               ),
    .user_port_axi_0_awid    ( slv.aw_id                 ),
    .user_port_axi_0_wvalid  ( slv.w_valid               ),
    .user_port_axi_0_wready  ( slv.w_ready               ),
    .user_port_axi_0_wlast   ( slv.w_last                ),
    .user_port_axi_0_wstrb   ( slv.w_strb                ),
    .user_port_axi_0_wdata   ( slv.w_data                ),
    .user_port_axi_0_bvalid  ( slv.b_valid               ),
    .user_port_axi_0_bready  ( slv.b_ready               ),
    .user_port_axi_0_bresp   ( slv.b_resp                ),
    .user_port_axi_0_bid     ( slv.b_id                  ),
    .user_port_axi_0_arvalid ( slv.ar_valid              ),
    .user_port_axi_0_arready ( slv.ar_ready              ),
    .user_port_axi_0_araddr  ( slv.ar_addr[AddrBits-1:0] ),
    .user_port_axi_0_arburst ( slv.ar_burst              ),
    .user_port_axi_0_arlen   ( slv.ar_len                ),
    .user_port_axi_0_arsize  ( slv.ar_size               ),
    .user_port_axi_0_arid    ( slv.ar_id                 ),
    .user_port_axi_0_rvalid  ( slv.r_valid               ),
    .user_port_axi_0_rready  ( slv.r_ready               ),
    .user_port_axi_0_rlast   ( slv.r_last                ),
    .user_port_axi_0_rresp   ( slv.r_resp                ),
    .user_port_axi_0_rid     ( slv.r_id                  ),
    .user_port_axi_0_rdata   ( slv.r_data                ),
    .wb_ctrl_adr             ( 30'(paddr_i[15:2])        ),
    .wb_ctrl_dat_w           ( pwdata_i                  ),
    .wb_ctrl_dat_r           ( prdata_o                  ),
    .wb_ctrl_sel             ( 4'hF                      ),
    .wb_ctrl_cyc             ( psel_i && penable_i       ),
    .wb_ctrl_stb             ( psel_i && penable_i       ),
    .wb_ctrl_ack             ( pready_o                  ),
    .wb_ctrl_we              ( pwrite_i                  ),
    .wb_ctrl_cti             ( 3'b000                    ),
    .wb_ctrl_bte             ( 2'b00                     ),
    .wb_ctrl_err             ( pslverr_o                 )
  );

endmodule
